import { chromium } from 'playwright';
import path from 'path';

const file = 'file://' + path.resolve('coding-agent-landscape.html');
const widths = [390, 480, 600, 640, 700, 768, 820, 900, 980, 1024, 1200, 1440];

const browser = await chromium.launch();
for (const w of widths) {
  const page = await browser.newPage({ viewport: { width: w, height: 900 } });
  await page.goto(file);
  const data = await page.evaluate(() => {
    const topnav = document.querySelector('.topnav');
    const topnavInfo = topnav ? {
      display: getComputedStyle(topnav).display,
      clientWidth: topnav.clientWidth,
      scrollWidth: topnav.scrollWidth,
      overflows: topnav.scrollWidth > topnav.clientWidth + 1,
    } : null;

    const tableWrap = document.querySelector('.table-wrap');
    const table = tableWrap ? tableWrap.querySelector('table') : null;
    const tableInfo = tableWrap ? {
      clientWidth: tableWrap.clientWidth,
      scrollWidth: table.scrollWidth,
      overflows: table.scrollWidth > tableWrap.clientWidth + 1,
    } : null;

    const figures = Array.from(document.querySelectorAll('figure.diagram')).map(f => {
      const svg = f.querySelector('svg');
      const fRect = f.getBoundingClientRect();
      const sRect = svg.getBoundingClientRect();
      return {
        figureWidth: Math.round(fRect.width),
        svgRenderedWidth: Math.round(sRect.width),
        svgNativeWidth: Number(svg.getAttribute('width')),
        deadSpacePct: Math.round((1 - sRect.width / fRect.width) * 100),
      };
    });

    return { topnavInfo, tableInfo, figures };
  });
  console.log(`--- width ${w} ---`);
  console.log(JSON.stringify(data, null, 2));
  await page.close();
}
await browser.close();
EOF
